      "Используйте заранее размороженное слоёное тесто. Мелко порубите охлаждённую баранину и лук ножом, смешайте с зирой и солью. Если мясо постное, вмешайте чайную ложку холодной воды на порцию.",
      "Раскатайте тесто до толщины 2–3 мм и нарежьте на квадраты. Распределите начинку, защипните края треугольником. Уложите швом вниз на бумагу для выпечки.",
