      "Два ломтика хлеба на порцию смажьте тончайшим слоем масла снаружи, горчицей изнутри. Уложите ветчину и половину тёртого сыра, закройте сэндвич.",
      "Распределите по верху бешамель, посыпьте оставшимся сыром. Пеките на противне 10–13 минут, пока сыр не запузырится и края не станут золотистыми.",
