      "Очищенный картофель нарежьте кружками толщиной 2 мм. После нарезки не промывайте, чтобы сохранить крахмал. Уложите слоями в форму, залейте сливочной смесью почти до верхнего ряда.",
      "Накройте фольгой и запекайте 40 минут. Снимите фольгу и пеките ещё 20–25 минут: нож должен легко проходить до дна, а верх стать золотистым. Оставьте на 5 минут перед подачей.",
