      "Пеките 35–45 минут; перец переверните, как только кожица потемнеет с одной стороны. Выньте мягкие овощи по готовности и на 10 минут накройте миской.",
      "Снимите кожицу, удалите семечки из перца, разберите мякоть на длинные полоски. Перемешайте с соком с противня, чесноком, солью и остальным маслом. Подайте тёплыми на подсушенном хлебе.",
