      "Взбейте натуральный йогурт с 50–80 мл холодной питьевой воды до текучей консистенции. Добавьте огурец, чеснок и укроп.",
      "Разотрите часть орехов в крупную крошку и вмешайте. Разлейте суп холодным, добавьте растительное масло и оставшиеся рубленые орехи.",
