      "В 250 мл воды с солью проварите рубленый щавель 2–3 минуты, пока листья не изменят цвет. Охладите кастрюлю в миске с холодной водой.",
      "Разотрите зелёный лук с укропом и маслом. Смешайте с хлебом в тарелке, залейте прохладным щавелевым отваром и подайте сразу.",
