      "В кастрюле обжарьте лук до мягкости, добавьте чеснок, томатную пасту и паприку. Через минуту вмешайте тёртые помидоры. Томите ещё 5–6 минут до насыщенного цвета.",
      "Добавьте 210 мл горячей воды и соль, проварите 8–10 минут и пробейте блендером. В тарелку положите сыр кубиками и полоски лаваша, влейте горячий суп, добавьте сметану и зелень.",
