      "Разогрейте масло в небольшой сковороде. Вылейте смесь слоем до сантиметра, уменьшите нагрев и готовьте 3–5 минут, пока края не подрумянятся, а верх почти полностью схватится.",
      "Переверните лепёшку с помощью тарелки, допеките ещё минуту-полторы. Подайте сразу с дольками свежего помидора.",
